        private void CheckUnionMembers(BindingDiagnosticBag diagnostics)
        {
            if (declaration.Kind != DeclarationKind.Union)
            {
                return;
            }

            foreach (var member in GetMembersAndInitializers().NonTypeMembers)
            {
                switch (member)
                {
                    // Instance fields (but not backing fields of properties or associated fields of events,
                    // which report through their associated symbol below).
                    case SourceMemberFieldSymbol { IsStatic: false, AssociatedSymbol: null }:
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, member.GetFirstLocation());
                        break;

                    // Auto-properties (including get-only/set-only/get-set and explicit interface implementations)
                    // and properties that use the 'field' keyword.
                    case SourcePropertySymbolBase { IsStatic: false, IsAutoPropertyOrUsesFieldKeyword: true }:
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, member.GetFirstLocation());
                        break;

                    // Field-like events (declared without explicit accessor bodies).
                    case SourceEventSymbol { IsStatic: false, HasAssociatedField: true }:
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, member.GetFirstLocation());
                        break;

                    case SourceConstructorSymbol { MethodKind: MethodKind.Constructor } ctor:
                        CheckUnionConstructor(ctor, diagnostics);
                        break;
                }
            }
        }

        private static void CheckUnionConstructor(SourceConstructorSymbol ctor, BindingDiagnosticBag diagnostics)
        {
            if (ctor.ParameterCount == 1)
            {
                diagnostics.Add(ErrorCode.ERR_InstanceCtorWithOneParameterInUnion, ctor.GetFirstLocation());
            }

            ConstructorDeclarationSyntax syntax = ctor.GetSyntax();
            ConstructorInitializerSyntax? initializer = syntax.Initializer;

            if (initializer is null || initializer.Kind() != SyntaxKind.ThisConstructorInitializer)
            {
                // The constructor lacks a 'this' initializer entirely.
                diagnostics.Add(ErrorCode.ERR_UnionConstructorCallsDefaultConstructor, syntax.Identifier.GetLocation());
            }
            else if (initializer.ArgumentList.Arguments.Count == 0)
            {
                // The 'this()' initializer calls the default parameterless constructor.
                diagnostics.Add(ErrorCode.ERR_UnionConstructorCallsDefaultConstructor, initializer.ThisOrBaseKeyword.GetLocation());
            }
        }
